using Microsoft.VisualStudio.TestTools.UnitTesting;
using Store;

namespace Store.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    #region AddItem Tests

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotal()
    {
        _cart.AddItem("SKU-001", quantity: 1, price: 9.99m);

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(9.99m, total);
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_MultipliesPrice()
    {
        _cart.AddItem("SKU-001", quantity: 3, price: 5.00m);

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(15.00m, total);
    }

    [TestMethod]
    public void AddItem_MultipleDifferentItems_SumsCorrectly()
    {
        _cart.AddItem("SKU-001", quantity: 1, price: 10.00m);
        _cart.AddItem("SKU-002", quantity: 2, price: 5.50m);

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(21.00m, total);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantities()
    {
        _cart.AddItem("SKU-001", quantity: 1, price: 10.00m);
        _cart.AddItem("SKU-001", quantity: 2, price: 10.00m);

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(30.00m, total);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddItem_NullSku_ThrowsArgumentException()
    {
        _cart.AddItem(null!, quantity: 1, price: 10.00m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddItem_EmptySku_ThrowsArgumentException()
    {
        _cart.AddItem("", quantity: 1, price: 10.00m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void AddItem_ZeroQuantity_ThrowsArgumentOutOfRangeException()
    {
        _cart.AddItem("SKU-001", quantity: 0, price: 10.00m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void AddItem_NegativeQuantity_ThrowsArgumentOutOfRangeException()
    {
        _cart.AddItem("SKU-001", quantity: -1, price: 10.00m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRangeException()
    {
        _cart.AddItem("SKU-001", quantity: 1, price: -5.00m);
    }

    #endregion

    #region RemoveItem Tests

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-001", quantity: 2, price: 10.00m);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_OneOfMultipleItems_OnlyRemovesSpecifiedItem()
    {
        _cart.AddItem("SKU-001", quantity: 1, price: 10.00m);
        _cart.AddItem("SKU-002", quantity: 1, price: 20.00m);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(20.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    [ExpectedException(typeof(InvalidOperationException))]
    public void RemoveItem_NonExistentSku_ThrowsInvalidOperationException()
    {
        _cart.RemoveItem("SKU-MISSING");
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void RemoveItem_NullSku_ThrowsArgumentException()
    {
        _cart.RemoveItem(null!);
    }

    #endregion

    #region CalculateTotal Tests

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(0m, total);
    }

    [TestMethod]
    public void CalculateTotal_AfterAddAndRemove_ReflectsCurrentState()
    {
        _cart.AddItem("SKU-001", quantity: 1, price: 25.00m);
        _cart.AddItem("SKU-002", quantity: 1, price: 15.00m);
        _cart.RemoveItem("SKU-001");

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(15.00m, total);
    }

    [TestMethod]
    public void CalculateTotal_LargeQuantities_CalculatesCorrectly()
    {
        _cart.AddItem("SKU-001", quantity: 1000, price: 0.99m);

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(990.00m, total);
    }

    #endregion

    #region ApplyCoupon Tests

    [TestMethod]
    public void ApplyCoupon_ValidCode_ReducesTotal()
    {
        _cart.AddItem("SKU-001", quantity: 1, price: 100.00m);

        _cart.ApplyCoupon("SAVE10");

        Assert.IsTrue(_cart.CalculateTotal() < 100.00m);
    }

    [TestMethod]
    public void ApplyCoupon_PercentageDiscount_AppliesCorrectly()
    {
        _cart.AddItem("SKU-001", quantity: 1, price: 100.00m);

        _cart.ApplyCoupon("SAVE10");

        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void ApplyCoupon_NullCode_ThrowsArgumentException()
    {
        _cart.ApplyCoupon(null!);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void ApplyCoupon_EmptyCode_ThrowsArgumentException()
    {
        _cart.ApplyCoupon("");
    }

    [TestMethod]
    [ExpectedException(typeof(InvalidOperationException))]
    public void ApplyCoupon_InvalidCode_ThrowsInvalidOperationException()
    {
        _cart.ApplyCoupon("FAKECODE");
    }

    [TestMethod]
    [ExpectedException(typeof(InvalidOperationException))]
    public void ApplyCoupon_AppliedTwice_ThrowsInvalidOperationException()
    {
        _cart.AddItem("SKU-001", quantity: 1, price: 100.00m);
        _cart.ApplyCoupon("SAVE10");

        _cart.ApplyCoupon("SAVE10");
    }

    [TestMethod]
    public void ApplyCoupon_EmptyCart_TotalRemainsZero()
    {
        _cart.ApplyCoupon("SAVE10");

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    #endregion

    #region Integration / Edge Case Tests

    [TestMethod]
    public void FullWorkflow_AddItemsApplyCouponRemoveItem_CalculatesCorrectly()
    {
        _cart.AddItem("SKU-001", quantity: 2, price: 50.00m);
        _cart.AddItem("SKU-002", quantity: 1, price: 30.00m);
        _cart.ApplyCoupon("SAVE10");
        _cart.RemoveItem("SKU-002");

        // 2 * 50 = 100, minus 10% = 90; then remove SKU-002 (already discounted)
        decimal total = _cart.CalculateTotal();

        Assert.IsTrue(total > 0m);
    }

    [TestMethod]
    public void AddItem_PriceWithManyDecimalPlaces_HandledCorrectly()
    {
        _cart.AddItem("SKU-001", quantity: 3, price: 1.333m);

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(3.999m, total);
    }

    #endregion
}

